package main

import (
	"encoding/json"
	"errors"
	"io"
	"log"
	"net/http"
	"regexp"
	"strconv"
	"strings"
)

// maxBody is the largest accepted request body: 1 MiB values plus generous headroom.
const maxBody = 8 << 20

var keyPattern = regexp.MustCompile(`^[A-Za-z0-9_-]{1,64}$`)

// Handler serves the kvhttp routes backed by a Store.
type Handler struct {
	store *Store
}

// NewHandler returns an http.Handler backed by store.
func NewHandler(store *Store) *Handler {
	return &Handler{store: store}
}

func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	// Route on the raw request path so percent-encoded bytes are not
	// silently decoded into otherwise valid (or path-separating) characters.
	path, _, _ := strings.Cut(r.RequestURI, "?")
	switch {
	case path == "/health":
		h.health(w, r)
	case path == "/kv":
		h.listKeys(w, r)
	case strings.HasPrefix(path, "/kv/"):
		h.item(w, r, strings.TrimPrefix(path, "/kv/"))
	default:
		w.WriteHeader(http.StatusNotFound)
	}
}

func (h *Handler) health(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		methodNotAllowed(w, "GET")
		return
	}
	writeBody(w, http.StatusOK, "text/plain; charset=utf-8", []byte("ok"))
}

func (h *Handler) listKeys(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		methodNotAllowed(w, "GET")
		return
	}
	body, err := json.Marshal(h.store.Keys())
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	writeBody(w, http.StatusOK, "application/json", body)
}

func (h *Handler) item(w http.ResponseWriter, r *http.Request, key string) {
	if !keyPattern.MatchString(key) {
		w.WriteHeader(http.StatusBadRequest)
		return
	}
	switch r.Method {
	case http.MethodGet:
		v, ok := h.store.Get(key)
		if !ok {
			w.WriteHeader(http.StatusNotFound)
			return
		}
		writeBody(w, http.StatusOK, "application/octet-stream", v)
	case http.MethodPut:
		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBody))
		if err != nil {
			var tooLarge *http.MaxBytesError
			if errors.As(err, &tooLarge) {
				w.WriteHeader(http.StatusRequestEntityTooLarge)
			} else {
				w.WriteHeader(http.StatusBadRequest)
			}
			return
		}
		if h.store.Put(key, body) {
			w.WriteHeader(http.StatusCreated)
		} else {
			w.WriteHeader(http.StatusOK)
		}
	case http.MethodDelete:
		if h.store.Delete(key) {
			w.WriteHeader(http.StatusNoContent)
		} else {
			w.WriteHeader(http.StatusNotFound)
		}
	default:
		methodNotAllowed(w, "GET, PUT, DELETE")
	}
}

func methodNotAllowed(w http.ResponseWriter, allowed string) {
	w.Header().Set("Allow", allowed)
	w.WriteHeader(http.StatusMethodNotAllowed)
}

func writeBody(w http.ResponseWriter, status int, contentType string, body []byte) {
	hdr := w.Header()
	hdr.Set("Content-Type", contentType)
	hdr.Set("Content-Length", strconv.Itoa(len(body)))
	w.WriteHeader(status)
	if _, err := w.Write(body); err != nil {
		log.Printf("write response: %v", err)
	}
}

package main

import (
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func do(t *testing.T, h http.Handler, method, uri, body string) *httptest.ResponseRecorder {
	t.Helper()
	var r io.Reader
	if body != "" {
		r = strings.NewReader(body)
	}
	req := httptest.NewRequest(method, uri, r)
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec
}

func TestCRUD(t *testing.T) {
	h := NewHandler(NewStore())
	steps := []struct {
		method, uri, body string
		status            int
		want              string
	}{
		{"PUT", "/kv/a", "hello", 201, ""},
		{"GET", "/kv/a", "", 200, "hello"},
		{"PUT", "/kv/a", "world", 200, ""},
		{"GET", "/kv/a", "", 200, "world"},
		{"DELETE", "/kv/a", "", 204, ""},
		{"GET", "/kv/a", "", 404, ""},
		{"DELETE", "/kv/a", "", 404, ""},
	}
	for _, s := range steps {
		rec := do(t, h, s.method, s.uri, s.body)
		if rec.Code != s.status {
			t.Errorf("%s %s: status %d, want %d", s.method, s.uri, rec.Code, s.status)
		}
		if got := rec.Body.String(); got != s.want {
			t.Errorf("%s %s: body %q, want %q", s.method, s.uri, got, s.want)
		}
	}
}

func TestListing(t *testing.T) {
	h := NewHandler(NewStore())
	for _, k := range []string{"b", "a", "c"} {
		do(t, h, "PUT", "/kv/"+k, k)
	}
	rec := do(t, h, "GET", "/kv", "")
	if rec.Code != 200 {
		t.Fatalf("status %d", rec.Code)
	}
	if ct := rec.Header().Get("Content-Type"); ct != "application/json" {
		t.Errorf("content-type %q", ct)
	}
	if got := rec.Body.String(); got != `["a","b","c"]` {
		t.Errorf("body %s", got)
	}
	empty := do(t, NewHandler(NewStore()), "GET", "/kv", "")
	if got := empty.Body.String(); got != "[]" {
		t.Errorf("empty listing %s", got)
	}
}

func TestErrors(t *testing.T) {
	h := NewHandler(NewStore())
	cases := []struct {
		method, uri string
		status      int
	}{
		{"GET", "/kv/", 400},
		{"GET", "/kv/a/b", 400},
		{"GET", "/kv/bad.key", 400},
		{"GET", "/kv/a%2Fb", 400},
		{"GET", "/kv/" + strings.Repeat("a", 65), 400},
		{"GET", "/kv/" + strings.Repeat("a", 64), 404},
		{"GET", "/", 404},
		{"GET", "/nope", 404},
		{"GET", "/health/", 404},
		{"GET", "/kvx", 404},
		{"POST", "/health", 405},
		{"PUT", "/kv", 405},
		{"PATCH", "/kv/a", 405},
	}
	for _, c := range cases {
		if rec := do(t, h, c.method, c.uri, ""); rec.Code != c.status {
			t.Errorf("%s %s: status %d, want %d", c.method, c.uri, rec.Code, c.status)
		}
	}
}

// Command app serves an in-memory key-value HTTP API on 127.0.0.1.
//
// Usage: app <port>
package main

import (
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"strconv"
	"time"
)

func parsePort(s string) (int, bool) {
	n, err := strconv.Atoi(s)
	if err != nil || n < 1 || n > 65535 {
		return 0, false
	}
	return n, true
}

func main() {
	if len(os.Args) < 2 {
		usage()
	}
	port, ok := parsePort(os.Args[1])
	if !ok {
		usage()
	}

	addr := net.JoinHostPort("127.0.0.1", strconv.Itoa(port))
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		log.Fatalf("listen: %v", err)
	}
	srv := &http.Server{
		Handler:           NewHandler(NewStore()),
		ReadHeaderTimeout: 10 * time.Second,
		IdleTimeout:       60 * time.Second,
	}
	fmt.Printf("kvhttp listening on %s\n", addr)
	if err := srv.Serve(ln); err != nil {
		log.Fatalf("serve: %v", err)
	}
}

func usage() {
	fmt.Fprintln(os.Stderr, "usage: app <port>")
	os.Exit(2)
}

package main

import (
	"slices"
	"sync"
)

// Store is a concurrency-safe in-memory key-value store.
type Store struct {
	mu   sync.RWMutex
	data map[string][]byte
}

// NewStore returns an empty store.
func NewStore() *Store {
	return &Store{data: make(map[string][]byte)}
}

// Put stores value under key and reports whether the key was new.
func (s *Store) Put(key string, value []byte) (created bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, exists := s.data[key]
	s.data[key] = value
	return !exists
}

// Get returns the value stored under key. Stored values must not be mutated.
func (s *Store) Get(key string) ([]byte, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	v, ok := s.data[key]
	return v, ok
}

// Delete removes key and reports whether it was present.
func (s *Store) Delete(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, ok := s.data[key]
	delete(s.data, key)
	return ok
}

// Keys returns every key in ascending order.
func (s *Store) Keys() []string {
	s.mu.RLock()
	keys := make([]string, 0, len(s.data))
	for k := range s.data {
		keys = append(keys, k)
	}
	s.mu.RUnlock()
	slices.Sort(keys)
	return keys
}
